      'name: filter-severity-complete\ntype: pipeline\ndescription: Complete Log Severity Filtering Pipeline with JSON parsing, intelligent severity detection, and conditional routing.\nnamespace: production\nlabels:\n  category: log-processing\n  pattern: severity-filtering\nconfig:\n  input:\n    file:\n      paths:\n        - /var/log/app/*.log\n      codec: lines\n  pipeline:\n    processors:\n      - mapping: |-\n          let original = content().string()\n          let parsed = content().parse_json().catch(null)\n          let structured = $original.re_find_object("^(?P<timestamp>[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}) \\\\[(?P<level>[A-Z]+)\\\\] (?P<message>.+)$").catch({})\n          root = if $parsed != null { $parsed } else if $structured.timestamp != null { $structured } else { {"original_message":$original,"level":"UNKNOWN"} }\n          root.original_format = if $parsed != null { "json" } else if $structured.timestamp != null { "structured_text" } else { "unstructured_text" }\n          root.parsing_success = $parsed != null || $structured.timestamp != null\n      - mapping: |\n          root = this\n          root.processing_metadata = {\n            "processed_at": now(),\n            "node_id": env("NODE_ID").or("unknown"),\n            "pipeline_version": env("PIPELINE_VERSION").or("1.0")\n          }\n      - mapping: |-\n          root = this\n          let original = this.level.or("UNKNOWN").string().uppercase()\n          let text = this.message.or("").string().lowercase() + this.original_message.or("").string().lowercase()\n          let inferred = if $original == "UNKNOWN" {\n            if ["error", "fail", "exception", "crash", "critical", "fatal"].any(k -> $text.contains(k)) { "ERROR" }\n            else if ["warn", "warning", "alert", "caution", "timeout"].any(k -> $text.contains(k)) { "WARN" }\n            else { $original }\n          } else { $original }\n          root.level = {"FATAL":"ERROR", "SEVERE":"ERROR", "CRITICAL":"ERROR", "WARNING":"WARN"}.get($inferred).or($inferred)\n          root.original_level = $original\n      - mapping: |-\n          root = if this.level == "ERROR" || this.level == "WARN" { this } else { deleted() }\n          root.filter_metadata = if this.level == "ERROR" || this.level == "WARN" { {"passed_filter": true, "filter_reason":"severity_match", "filtering_timestamp": now()} } else { deleted() }\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - switch:\n            cases:\n              - check: this.level == "ERROR"\n                output:\n                  file:\n                    path: ${LOG_OUTPUT_PATH}/errors/${! timestamp_unix_date() }.json\n                    codec: lines\n              - check: this.level == "WARN"\n                output:\n                  stdout:\n                    codec: lines\n              - output:\n                  file:\n                    path: ${LOG_OUTPUT_PATH}/unrouted-logs.json\n                    codec: lines\nlogger:\n  level: INFO\n  format: json\nmetrics:\n  prometheus:\n    path: /metrics\n',
